import glob
import os
import sys

# Current interpreter
print("Current interpreter:", sys.executable)
print("sys.path:")
for p in sys.path:
    print("  ", p)

# Look for other python interpreters
candidates = []
for pat in ["/usr/bin/python*", "/usr/local/bin/python*", "/opt/*/bin/python*", "/usr/lib/python3*/"]:
    candidates += glob.glob(pat)
print("\nOther python candidates:")
for c in sorted(set(candidates)):
    print("  ", c)

# Search site-packages for pdf-related modules
print("\nSearching site-packages for pdf modules...")
seen = set()
for root in ["/usr/lib/python3", "/usr/local/lib/python3*", os.path.expanduser("~/.venv/lib")]:
    for d in glob.glob(root):
        for sp in glob.glob(os.path.join(d, "site-packages")):
            if sp in seen:
                continue
            seen.add(sp)
            try:
                entries = sorted(os.listdir(sp))
            except OSError:
                continue
            hits = [e for e in entries if any(
                k in e.lower() for k in ("pypdf", "py2pdf", "reportlab", "pdfminer", "fitz", "mupdf", "pdfplumber", "pikepdf", "pypdfium")
            )]
            if hits:
                print(sp, "->", hits)
print("Done.")

